import{_ as i,o as t,c as a,a0 as r}from"./chunks/framework.DScjKhBS.js";const u=JSON.parse('{"title":"Problem shape and measurable signals","description":"How to identify reviewer comprehension collapse before it becomes a quality incident.","frontmatter":{"title":"Problem shape and measurable signals","description":"How to identify reviewer comprehension collapse before it becomes a quality incident."},"headers":[],"relativePath":"reports/pr-review-continuity/01-problem-shape-and-signals.md","filePath":"reports/pr-review-continuity/01-problem-shape-and-signals.md"}'),s={name:"reports/pr-review-continuity/01-problem-shape-and-signals.md"};function o(n,e,l,d,p,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="problem-shape-and-measurable-signals" tabindex="-1">Problem shape and measurable signals <a class="header-anchor" href="#problem-shape-and-measurable-signals" aria-label="Permalink to &quot;Problem shape and measurable signals&quot;">​</a></h1><h2 id="what-this-period-looks-like-in-practice" tabindex="-1">What this period looks like in practice <a class="header-anchor" href="#what-this-period-looks-like-in-practice" aria-label="Permalink to &quot;What this period looks like in practice&quot;">​</a></h2><p>The risk is not just &quot;reviews are slower.&quot; It is a combined degradation:</p><ul><li>The primary reviewer is unavailable, overloaded, or context-starved</li><li>Remaining reviewers can approve syntax and style but not architectural intent</li><li>PRs increasingly contain AI-generated or AI-expanded changes that are fast to produce but expensive to reason about</li></ul><p>From existing project research, this aligns with the observed bottleneck pattern: review consistency and depth vary materially by reviewer availability, and missed edge cases can rise when first-pass review quality drops.</p><hr><h2 id="early-warning-indicators" tabindex="-1">Early warning indicators <a class="header-anchor" href="#early-warning-indicators" aria-label="Permalink to &quot;Early warning indicators&quot;">​</a></h2><p>Track these weekly at repo level:</p><ol><li><strong>Time to first meaningful review</strong> (not first emoji/comment)</li><li><strong>Median PR size</strong> (changed lines, files touched)</li><li><strong>Review depth proxy</strong> (comments that address design/logic vs style-only)</li><li><strong>Rework churn</strong> (lines replaced soon after merge)</li><li><strong>Post-merge regressions</strong> (defects/reverts per 10 merged PRs)</li><li><strong>Review concentration</strong> (% approvals from top 1-2 reviewers)</li></ol><p>If these trend in the wrong direction together, comprehension is already degrading.</p><hr><h2 id="quantitative-guardrails" tabindex="-1">Quantitative guardrails <a class="header-anchor" href="#quantitative-guardrails" aria-label="Permalink to &quot;Quantitative guardrails&quot;">​</a></h2><p>Use explicit, team-visible thresholds:</p><ul><li><strong>PR size target:</strong> keep most PRs in a &quot;single-session reviewable&quot; range</li><li><strong>Single review session cap:</strong> timebox focused reviews; split work if exceeding cap</li><li><strong>Queue SLA:</strong> cap waiting time for first substantive review</li><li><strong>Reviewer concentration limit:</strong> avoid depending on one person for most critical approvals</li></ul><p>The exact thresholds should be calibrated to team size and domain risk, but hard limits outperform informal norms during constrained periods.</p><hr><h2 id="why-this-matters-now" tabindex="-1">Why this matters now <a class="header-anchor" href="#why-this-matters-now" aria-label="Permalink to &quot;Why this matters now&quot;">​</a></h2><p>When throughput pressure rises, teams default to &quot;approve to unblock.&quot; That creates hidden debt:</p><ul><li>Design intent goes undocumented</li><li>Security assumptions are not challenged</li><li>AI suggestions are accepted on output plausibility instead of process verification</li></ul><p>This moves risk downstream into incidents, hotfixes, and slower future change velocity.</p><hr><p><strong>Next:</strong> <a href="./reports/pr-review-continuity/02-failure-modes-and-risk-model.html">Failure modes and risk model</a></p>',22)])])}const m=i(s,[["render",o]]);export{u as __pageData,m as default};
